  [402668] = { "Vampiric Embraceのタレントを対象に適用し、$D1かけて対象に$N1のShadowダメージを与え、対象に与えたShadow呪文ダメージの$N3%に等しいmanaをパーティメンバー全員に与えます。", "$N2秒ごとに$N1のShadowダメージを受けます。プリーストがこの目標に与えたShadow呪文ダメージの$N3%に等しいmanaを、そのプリーストのパーティーが得ます。", 0x0fe3e73d, 0x3bf17666, "uu" },
  [402789] = { "$D1の間、虚空の目を呼び出して共に戦わせます。目は対象にさまざまな呪いをかけることができます。", nil, 0x305d9a60, nil, "um" },
  [402799] = { "自らの魂の欠片を割り取り、自分の小さな分身を$N1体動かします。分身はメイス、剣、斧で現在の対象を攻撃し、命中した対象の攻撃速度、攻撃力、armorをそれぞれ低下させます。", nil, 0x15c256c1, nil, "um" },
  [402848] = { "脚部にPrayer of Mendingのルーンを刻みます：\r\n\n$I1\r\n対象に呪文をかけ、次にダメージを受けるか非周期の治療を受けたときに$N1回復させます。回復が起こると、Prayer of Mendingは$N2ヤード以内のパーティーまたはレイドのメンバーに移ります。最大$N3回移り、移るたびに$D1持続します。この呪文は術者ごとに同時に一体の対象にしかかけられません。", nil, 0x2bda4bfd, nil, "um" },
  [402849] = { "手袋にShadow Word: Deathのルーンを刻みます：\r\n\n$I1\r\n闇の束縛の言葉で、対象に$N1のShadowダメージを与えます。対象がShadow Word: Deathで倒れなかった場合、術者は対象に与えようとしたダメージの$N2%に等しいダメージを受けます。", nil, 0x139a0879, nil, "um" },
  [402850] = { "外套にSoul Wardingのルーンを刻みます：\r\n\n$I1\r\nPower Word: Shieldのクールダウンを$D1短縮し、mana消費を$N2%減らします。", nil, 0x154e3993, nil, "um" },
  [402852] = { "脚部にHomunculiのルーンを刻みます：\r\n\n$I1\r\n魂のかけらを切り離して自分の小さな分身を$N1体動かし、メイス、剣、斧で現在の対象を攻撃させます。命中した対象の攻撃速度、攻撃力、armorをそれぞれ低下させます。", nil, 0xd5759004, nil, "um" },
  [402853] = { "外套にBinding Healのルーンを刻みます：\r\n\n$I1\r\n味方の対象と術者を$N1回復します。脅威は低いです。", nil, 0x992a730c, nil, "um" },
  [402854] = { "脚部にShared Painのルーンを刻みます：\r\n\n$I1\r\nShadow Word: Painが、$N2ヤード以内の近くの対象最大$N1体にも効果を及ぼすようになります。", nil, 0xd899d8ce, nil, "um" },
  [402855] = { "ブーツにPain Suppressionのルーンを刻みます：\r\n\n$I1\r\n$D1の間、味方の対象が受けるすべてのダメージを即座に$N1%減少させ、Dispel効果への耐性を$N2%上昇させます。", nil, 0xb2fd4d86, nil, "um" },
  [402857] = { "外套にVampiric Touchのルーンを刻みます：\r\n\n$I1\r\nVampiric Embraceのタレントを対象に適用し、対象に$D1かけて$N1のShadowダメージを与えます。さらに対象に与えたShadow呪文のダメージの$N3%に等しいmanaを、すべてのパーティーメンバーが得ます。", nil, 0x8340998c, nil, "um" },
  [402859] = { "手袋にCircle of Healingのルーンを刻みます：\r\n\n$I1\r\n対象のプレイヤーから$N1ヤード以内にいる、そのプレイヤーのパーティーメンバー全員を$N2回復します。", nil, 0x6fa8939a, nil, "um" },
  [402861] = { "脚部にShadowfiendのルーンを刻みます：\r\n\n$I1\r\n影の魔物を作り出して対象を攻撃させます。Shadowfiendが攻撃すると、術者はmanaを$N1%得ます。$D1持続します。", nil, 0x4c1dccff, nil, "um" },
  [402862] = { "手袋にPenanceのルーンを刻みます：\r\n\n$I1\r\n対象に聖なる光の連撃を放ち、敵には$N1のHolyダメージを、味方には$N2の治療を、即座に、そして$D2の間$D1ごとに与えます。", nil, 0x52211170, nil, "um" },
  [402864] = { "兜にEye of the Voidのルーンを刻みます：\r\n\n$I1\r\n虚無の目を呼び出し、$D1の間自分のために戦わせます。目は対象にさまざまな呪いをかけられます。", nil, 0x08eaafc7, nil, "um" },
  [402911] = { "武器ダメージの$N1%を与える猛烈な一撃です。Enrage、Berserker Rage、Bloodrageのいずれかが有効な間のみ使用できます。Enrage、Berserker Rage、Bloodrageが有効な間に他の近接アビリティを使うたびに、Raging Blowの残りクールダウンが$N2秒短縮されます。", nil, 0xc369b8a3, nil, "um" },
  [402913] = { "$D1かけて最大healthの$N1%を回復しますが、Enrage、Berserker Rage、Bloodrageのいずれかが有効な間のみ使用できます。Stunnedの状態でも使用できます。", "$N2秒ごとに最大healthの$N1%を回復しています。", 0x8c9eb59e, 0x1fa7c1e1, "uu" },
  [402927] = { "即座に対象を攻撃して$N1のダメージを与え、最大healthの$N2%を回復します。取るに足らない敵以外を倒してから$D1以内にのみ使用できます。", nil, 0xa6a325bb, nil, "um" },
